package com.citacloud.app.models; import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="detalle_receta") public class DetalleReceta {@Id @GeneratedValue private UUID id; @Column(name="receta_id") private UUID recetaId; private String medicamento; @Column(name="principio_activo") private String principioActivo; private String concentracion; @Column(name="forma_farmaceutica") private String formaFarmaceutica; private String dosis; @Column(name="via_administracion") private String viaAdministracion; private String frecuencia; private String duracion; private String cantidad; @Column(columnDefinition="TEXT") private String indicaciones; public UUID getId(){return id;} public UUID getRecetaId(){return recetaId;} public String getMedicamento(){return medicamento;} public String getPrincipioActivo(){return principioActivo;} public String getConcentracion(){return concentracion;} public String getFormaFarmaceutica(){return formaFarmaceutica;} public String getDosis(){return dosis;} public String getViaAdministracion(){return viaAdministracion;} public String getFrecuencia(){return frecuencia;} public String getDuracion(){return duracion;} public String getCantidad(){return cantidad;} public String getIndicaciones(){return indicaciones;} public void setRecetaId(UUID v){recetaId=v;} public void setMedicamento(String v){medicamento=v;} public void setPrincipioActivo(String v){principioActivo=v;} public void setConcentracion(String v){concentracion=v;} public void setFormaFarmaceutica(String v){formaFarmaceutica=v;} public void setDosis(String v){dosis=v;} public void setViaAdministracion(String v){viaAdministracion=v;} public void setFrecuencia(String v){frecuencia=v;} public void setDuracion(String v){duracion=v;} public void setCantidad(String v){cantidad=v;} public void setIndicaciones(String v){indicaciones=v;} }
